begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions,pg_catalog;
select no_plan();
select has_function('public','member_workspaces',array[]::text[],'Shared workspace return path exists');
select has_function('public','task_assign',array['uuid','uuid','text','uuid'],'Trusted Admin assignment exists');
select has_function('public','task_contribute',array['uuid','uuid','text','text','text','boolean'],'Narrow contribution exists');
insert into auth.users(id,email,email_confirmed_at) values
('71000000-0000-4000-8000-000000000001','admin@example.invalid',now()),('71000000-0000-4000-8000-000000000002','member-b@example.invalid',now()),('71000000-0000-4000-8000-000000000003','member-c@example.invalid',now()),('71000000-0000-4000-8000-000000000004','foreign@example.invalid',now());
select set_config('request.jwt.claims','{"sub":"71000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
insert into wedding_private.weddings(id,owner_user_id,title,city,wedding_date,is_tentative) values('71200000-0000-4000-8000-000000000001',wedding_private.caller_uid(),'Shared synthetic wedding','Test city','2026-11-20',false);
insert into wedding_private.ceremonies(id,wedding_id,title,guest_count) values('71300000-0000-4000-8000-000000000001','71200000-0000-4000-8000-000000000001','Synthetic ceremony',100);
insert into wedding_private.tasks(id,wedding_id,title,owner_name) values
('71100000-0000-4000-8000-000000000001','71200000-0000-4000-8000-000000000001','Work for B',null),
('71100000-0000-4000-8000-000000000002','71200000-0000-4000-8000-000000000001','Work for C',null),
('71100000-0000-4000-8000-000000000003','71200000-0000-4000-8000-000000000001','Legacy offline name','Member B'),
('71100000-0000-4000-8000-000000000004','71200000-0000-4000-8000-000000000001','Unfinished prerequisite',null),
('71100000-0000-4000-8000-000000000005','71200000-0000-4000-8000-000000000001','Blocked assigned work',null);
update wedding_private.tasks set prerequisite_task_id='71100000-0000-4000-8000-000000000004' where id='71100000-0000-4000-8000-000000000005';
insert into wedding_private.cost_items(id,wedding_id,title,pricing_basis,fixed_estimate_paise) values('71400000-0000-4000-8000-000000000001','71200000-0000-4000-8000-000000000001','Private financial record','FIXED',10000);
update wedding_private.cost_items set state='COMMITTED',commitment_paise=10000 where id='71400000-0000-4000-8000-000000000001';
insert into wedding_private.cash_entries(wedding_id,cost_item_id,kind,amount_paise,occurred_on,intent_key) values('71200000-0000-4000-8000-000000000001','71400000-0000-4000-8000-000000000001','PAYMENT',500,'2026-10-31','collaboration-test');
select public.membership_grant('71200000-0000-4000-8000-000000000001','71000000-0000-4000-8000-000000000002');
select public.membership_grant('71200000-0000-4000-8000-000000000001','71000000-0000-4000-8000-000000000003');
create function pg_temp.v() returns text language sql security definer as $$select state_version::text from wedding_private.weddings where id='71200000-0000-4000-8000-000000000001'$$;
create temporary table protected_state as select jsonb_build_object('costs',(select jsonb_agg(to_jsonb(t)) from wedding_private.cost_items t),'cash',(select jsonb_agg(to_jsonb(t)) from wedding_private.cash_entries t),'date',(select wedding_date from wedding_private.weddings where id='71200000-0000-4000-8000-000000000001')) snapshot;
set local role authenticated;
select lives_ok($$select public.task_assign('71200000-0000-4000-8000-000000000001','71100000-0000-4000-8000-000000000001',pg_temp.v(),'71000000-0000-4000-8000-000000000002')$$,'Admin assigns B by account membership before activation');
select lives_ok($$select public.task_assign('71200000-0000-4000-8000-000000000001','71100000-0000-4000-8000-000000000002',pg_temp.v(),'71000000-0000-4000-8000-000000000003')$$,'Admin assigns C');
select lives_ok($$select public.task_assign('71200000-0000-4000-8000-000000000001','71100000-0000-4000-8000-000000000005',pg_temp.v(),'71000000-0000-4000-8000-000000000002')$$,'Admin assigns blocked work');
select throws_ok($$select public.task_assign('71200000-0000-4000-8000-000000000001','71100000-0000-4000-8000-000000000001',pg_temp.v(),'71000000-0000-4000-8000-000000000004')$$,'42501',null,'Unrelated account cannot be assigned');
select throws_ok($$select public.task_assign('71200000-0000-4000-8000-000000000001','71100000-0000-4000-8000-000000000001','999999','71000000-0000-4000-8000-000000000002')$$,'40001',null,'Stale assignment rejected');
reset role;
update wedding_private.weddings set state='ACTIVE' where id='71200000-0000-4000-8000-000000000001';
select public.update_task('71200000-0000-4000-8000-000000000001','71100000-0000-4000-8000-000000000001',pg_temp.v(),'status','{"status":"TO_DO","confirmed_by":"Synthetic Admin confirmation"}',false,false);
select set_config('request.jwt.claims','{"sub":"71000000-0000-4000-8000-000000000002","role":"authenticated"}',true);
set local role authenticated;
select is(jsonb_array_length(public.member_workspaces()),1,'Accepted Member can discover joined workspace');
select ok(not (public.member_workspaces()->0?'budget_ceiling_paise'),'Shared workspace list contains no budget');
select is((select count(*) from jsonb_array_elements(public.planning_read('71200000-0000-4000-8000-000000000001')->'tasks')t where (t->>'assigned_to_me')::boolean),2::bigint,'B sees exactly own assigned tasks');
select ok(not(public.planning_read('71200000-0000-4000-8000-000000000001')->'wedding'?'budget_ceiling_paise'),'Member planning excludes budget');
select ok(not(public.planning_read('71200000-0000-4000-8000-000000000001') ?| array['costs','cash','finance','proposals','audit']),'Member planning excludes all restricted payloads');
select lives_ok($$select public.task_contribute('71200000-0000-4000-8000-000000000001','71100000-0000-4000-8000-000000000001',pg_temp.v(),'IN_PROGRESS','Coordinating with family',false)$$,'B updates assigned status and note');
reset role;
select is((select status_confirmed_by from wedding_private.tasks where id='71100000-0000-4000-8000-000000000001'),null::text,'Member status change cannot retain an earlier status confirmation');
select is((select status_confirmed_at from wedding_private.tasks where id='71100000-0000-4000-8000-000000000001'),null::timestamptz,'Old confirmation timestamp is cleared on actual status change');
set local role authenticated;
select is((public.planning_read('71200000-0000-4000-8000-000000000001')->'wedding'->>'state_version'),pg_temp.v(),'Member sees exact current version');
select throws_ok($$select public.task_contribute('71200000-0000-4000-8000-000000000001','71100000-0000-4000-8000-000000000002',pg_temp.v(),'IN_PROGRESS','forged',false)$$,'42501',null,'B cannot update C work');
select throws_ok($$select public.task_contribute('71200000-0000-4000-8000-000000000001','71100000-0000-4000-8000-000000000003',pg_temp.v(),'IN_PROGRESS','forged',false)$$,'42501',null,'Offline owner name grants no account permission');
select throws_ok($$select public.task_assign('71200000-0000-4000-8000-000000000001','71100000-0000-4000-8000-000000000001',pg_temp.v(),'71000000-0000-4000-8000-000000000003')$$,'42501',null,'Member cannot reassign');
select throws_ok($$select public.task_members('71200000-0000-4000-8000-000000000001')$$,'42501',null,'Member cannot enumerate Admin assignment roster');
select throws_ok($$select public.update_task('71200000-0000-4000-8000-000000000001','71100000-0000-4000-8000-000000000001',pg_temp.v(),'details','{"due_date":"2027-01-01"}',false,false)$$,'42501',null,'Member cannot change deadlines through Admin RPC');
select throws_ok($$update public.tasks set due_date='2027-01-01' where id='71100000-0000-4000-8000-000000000001'$$,'42501',null,'Direct task bypass remains denied');
select is(public.finance_read('71200000-0000-4000-8000-000000000001'),null::jsonb,'Member cannot read finance RPC');
select is((select count(*) from public.cost_items),0::bigint,'Member cannot read protected finance view');
select throws_ok($$select public.membership_grant('71200000-0000-4000-8000-000000000001','71000000-0000-4000-8000-000000000004')$$,'42501',null,'Member cannot invite or grant');
select throws_ok($$select public.delete_wedding('71200000-0000-4000-8000-000000000001','Shared synthetic wedding',pg_temp.v())$$,'42501',null,'Member cannot delete wedding');
select throws_ok($$select public.initialize_guest_count('71200000-0000-4000-8000-000000000001','71300000-0000-4000-8000-000000000001',pg_temp.v(),150,true)$$,'42501',null,'Member cannot initialize guest count');
select throws_ok($$select public.adapt_propose('71200000-0000-4000-8000-000000000001','71300000-0000-4000-8000-000000000001',pg_temp.v(),150,null)$$,'42501',null,'Member cannot propose ADAPT');
select throws_ok($$select public.task_contribute('71200000-0000-4000-8000-000000000001','71100000-0000-4000-8000-000000000005',pg_temp.v(),'COMPLETED','',false)$$,'23514',null,'Member cannot override unfinished prerequisite');
select throws_ok($$select public.task_contribute('71200000-0000-4000-8000-000000000001','71100000-0000-4000-8000-000000000001','999999','TO_DO','',false)$$,'40001',null,'Stale contribution rejected');
select throws_ok($$select public.task_contribute('71200000-0000-4000-8000-000000000001','71100000-0000-4000-8000-000000000001',pg_temp.v(),'IN_PROGRESS',repeat('x',501),false)$$,'22023',null,'Progress note length enforced in DB');
select lives_ok($$select public.task_contribute('71200000-0000-4000-8000-000000000001','71100000-0000-4000-8000-000000000001',pg_temp.v(),'COMPLETED','Done with coordination',false)$$,'Assigned Member completes work');
select throws_ok($$select public.task_contribute('71200000-0000-4000-8000-000000000001','71100000-0000-4000-8000-000000000001',pg_temp.v(),'TO_DO','',false)$$,'23514',null,'Completed work requires deliberate reopen confirmation');
select lives_ok($$select public.task_contribute('71200000-0000-4000-8000-000000000001','71100000-0000-4000-8000-000000000001',pg_temp.v(),'TO_DO','Needs another check',true)$$,'Explicit confirmed reopen works');
reset role;
select is((select progress_updated_by from wedding_private.tasks where id='71100000-0000-4000-8000-000000000001'),'71000000-0000-4000-8000-000000000002'::uuid,'Trusted account author recorded');
select is((select progress_note from wedding_private.tasks where id='71100000-0000-4000-8000-000000000001'),'Needs another check','Admin sees saved Member note');
select is((select count(*) from wedding_private.audit_events where action='TASK_PROGRESS_UPDATED' and wedding_id='71200000-0000-4000-8000-000000000001'),3::bigint,'All successful Member updates audited');
select is(jsonb_build_object('costs',(select jsonb_agg(to_jsonb(t)) from wedding_private.cost_items t),'cash',(select jsonb_agg(to_jsonb(t)) from wedding_private.cash_entries t),'date',(select wedding_date from wedding_private.weddings where id='71200000-0000-4000-8000-000000000001')),(select snapshot from protected_state),'Finance and wedding dates preserved');
create temporary table atomic_before as select to_jsonb(t) task,pg_temp.v() version from wedding_private.tasks t where id='71100000-0000-4000-8000-000000000001';
create function pg_temp.audit_failure() returns trigger language plpgsql as $$begin if new.action='TASK_PROGRESS_UPDATED' then raise exception using errcode='P0001',message='Synthetic audit failure';end if;return new;end;$$;
create trigger zz_collaboration_failure before insert on wedding_private.audit_events for each row execute function pg_temp.audit_failure();
set local role authenticated;
select throws_ok($$select public.task_contribute('71200000-0000-4000-8000-000000000001','71100000-0000-4000-8000-000000000001',pg_temp.v(),'IN_PROGRESS','Must roll back',false)$$,'P0001',null,'Audit failure aborts complete contribution');
reset role;
select is((select to_jsonb(t) from wedding_private.tasks t where id='71100000-0000-4000-8000-000000000001'),(select task from atomic_before),'Failed contribution rolls back task and note');
select is(pg_temp.v(),(select version from atomic_before),'Failed contribution rolls back version');
drop trigger zz_collaboration_failure on wedding_private.audit_events;
select set_config('request.jwt.claims','{"sub":"71000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
set local role authenticated;
select lives_ok($$select public.update_task('71200000-0000-4000-8000-000000000001','71100000-0000-4000-8000-000000000003',pg_temp.v(),'details','{"title":"Admin retained edit","due_date":"2026-11-01"}',false,false)$$,'Existing Admin task edit preserved');
select lives_ok($$select public.task_assign('71200000-0000-4000-8000-000000000001','71100000-0000-4000-8000-000000000001',pg_temp.v(),'71000000-0000-4000-8000-000000000003')$$,'Admin reassigns B work to C');
select set_config('request.jwt.claims','{"sub":"71000000-0000-4000-8000-000000000002","role":"authenticated"}',true);
select throws_ok($$select public.task_contribute('71200000-0000-4000-8000-000000000001','71100000-0000-4000-8000-000000000001',pg_temp.v(),'IN_PROGRESS','',false)$$,'42501',null,'Old assignee loses write immediately');
select set_config('request.jwt.claims','{"sub":"71000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
select public.membership_revoke('71200000-0000-4000-8000-000000000001','71000000-0000-4000-8000-000000000003');
select set_config('request.jwt.claims','{"sub":"71000000-0000-4000-8000-000000000003","role":"authenticated"}',true);
select throws_ok($$select public.task_contribute('71200000-0000-4000-8000-000000000001','71100000-0000-4000-8000-000000000001',pg_temp.v(),'IN_PROGRESS','',false)$$,'42501',null,'Revoked assigned Member denied immediately');
select is(public.planning_read('71200000-0000-4000-8000-000000000001'),null::jsonb,'Revoked Member cannot read planning');
select is(public.member_workspaces(),'[]'::jsonb,'Revoked Member cannot discover old workspace');
select set_config('request.jwt.claims','{"sub":"71000000-0000-4000-8000-000000000004","role":"authenticated"}',true);
select throws_ok($$select public.task_contribute('71200000-0000-4000-8000-000000000001','71100000-0000-4000-8000-000000000001',pg_temp.v(),'IN_PROGRESS','',false)$$,'42501',null,'Unrelated account denied');
select is(public.planning_read('71200000-0000-4000-8000-000000000001'),null::jsonb,'Unrelated account cannot read planning');
select is(public.member_workspaces(),'[]'::jsonb,'Unrelated account has no shared workspace');
select set_config('request.jwt.claims','{"sub":"71000000-0000-4000-8000-000000000002","role":"authenticated","is_anonymous":true}',true);
select throws_ok($$select public.task_contribute('71200000-0000-4000-8000-000000000001','71100000-0000-4000-8000-000000000005',pg_temp.v(),'IN_PROGRESS','',false)$$,'42501',null,'Anonymous Auth identity denied');
select is(public.member_workspaces(),'[]'::jsonb,'Anonymous Auth identity cannot discover shared workspaces');
set local role anon;
select throws_ok($$select public.member_workspaces()$$,'42501',null,'Anonymous role cannot call shared workspace list');
select throws_ok($$select public.task_contribute('71200000-0000-4000-8000-000000000001','71100000-0000-4000-8000-000000000001','0','TO_DO','',false)$$,'42501',null,'Anonymous database role denied');
reset role;
select ok(not pg_has_role('authenticated','wedding_contributor','MEMBER'),'Clients cannot assume contributor role');
select ok(not has_column_privilege('wedding_contributor','wedding_private.weddings','budget_ceiling_paise','SELECT'),'Contributor cannot read budget column');
select ok(not has_table_privilege('wedding_contributor','wedding_private.cash_entries','SELECT'),'Contributor cannot read payments');
select ok(not has_column_privilege('wedding_contributor','wedding_private.tasks','assigned_member_id','UPDATE'),'Contributor cannot update assignment column');
select ok(not has_column_privilege('wedding_contributor','wedding_private.tasks','due_date','UPDATE'),'Contributor cannot update deadline column');
select ok((select bool_and(relrowsecurity and relforcerowsecurity) from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname in('wedding_private','wedding_access') and c.relkind='r'),'All forced RLS retained');
select set_config('request.jwt.claims','{"sub":"71000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
set local role authenticated;
select lives_ok($$select public.delete_wedding('71200000-0000-4000-8000-000000000001','Shared synthetic wedding',pg_temp.v())$$,'Complete Delete Wedding still handles Member-assigned tasks');
reset role;
select is((select count(*) from wedding_private.tasks where wedding_id='71200000-0000-4000-8000-000000000001'),0::bigint,'No assigned task orphan remains');
select is((select count(*) from wedding_access.memberships where wedding_id='71200000-0000-4000-8000-000000000001'),0::bigint,'No membership orphan remains');
select * from finish();
rollback;
